import base64, io, json, zipfile
from http.server import BaseHTTPRequestHandler

TMPL_ANTEOJOS = {'[Content_Types].xml': '', '_rels/.rels': '', 'word/header1.xml': '', 'word/styles.xml': '', 'word/numbering.xml': '', 'word/document.xml': '', 'word/settings.xml': '', 'word/fontTable.xml': '', 'word/footnotes.xml': '', 'word/endnotes.xml': '', 'word/webSettings.xml': '', 'customXml/itemProps1.xml': '', 'customXml/item1.xml': '', 'docProps/app.xml': '', 'docProps/core.xml': '', 'word/media/image1.png': '', 'word/media/image2.png': '', 'word/theme/theme1.xml': '', 'word/glossary/styles.xml': '', 'word/glossary/document.xml': '', 'word/glossary/settings.xml': '', 'word/glossary/fontTable.xml': '', 'word/glossary/webSettings.xml': '', 'word/_rels/document.xml.rels': '', 'word/_rels/header1.xml.rels': '', 'word/glossary/_rels/document.xml.rels': '', 'customXml/_rels/item1.xml.rels': ''}
TMPL_AUDIO = {'[Content_Types].xml': '', '_rels/.rels': '', 'word/styles.xml': '', 'word/document.xml': '', 'word/settings.xml': '', 'word/fontTable.xml': '', 'word/footnotes.xml': '', 'word/endnotes.xml': '', 'word/webSettings.xml': '', 'customXml/itemProps1.xml': '', 'customXml/item1.xml': '', 'docProps/app.xml': '', 'docProps/core.xml': '', 'word/media/image1.png': '', 'word/media/image2.png': '', 'word/theme/theme1.xml': '', 'word/_rels/document.xml.rels': '', 'customXml/_rels/item1.xml.rels': ''}

def fmt_precio(precio_raw):
    n = int(precio_raw.replace(".","").replace(",","").strip())
    return n, "{:,}".format(n).replace(",",".")

def generar_anteojos(data):
    fecha      = data.get("fecha","")
    nro_res    = data.get("nroRes","")
    nro_exp    = data.get("nroExp","")
    paciente   = data.get("paciente","")
    insumo     = data.get("insumo","")
    n, fmt     = fmt_precio(data.get("precio","0"))
    imp_letras = data.get("importeLetras","")
    pu = "$ " + fmt
    pt = "$ " + fmt + ",00"
    im = "$ " + fmt + ", 00"
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zout:
        for name, b64 in TMPL_ANTEOJOS.items():
            raw = base64.b64decode(b64)
            if name == "[Content_Types].xml":
                xml = raw.decode("utf-8").replace(
                    "application/vnd.ms-word.template.macroEnabledTemplate.main+xml",
                    "application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml")
                raw = xml.encode("utf-8")
            elif name == "word/document.xml":
                xml = raw.decode("utf-8")
                xml = xml.replace("__FECHA__", fecha).replace("__NRO_RES__", nro_res)
                xml = xml.replace("__NRO_EXP__", nro_exp).replace("__PACIENTE__", paciente)
                xml = xml.replace("__INSUMO_CORTO__", insumo)
                xml = xml.replace("__PRECIO_UNIT__", pu).replace("__PRECIO_TOTAL__", pt)
                xml = xml.replace("__IMPORTE__", im).replace("__IMPORTE_LETRAS__", imp_letras)
                raw = xml.encode("utf-8")
            zout.writestr(name, raw)
    return buf.getvalue()

def generar_audio(data):
    fecha       = data.get("fecha","")
    nro_res     = data.get("nroRes","")
    nro_exp     = data.get("nroExp","")
    paciente    = data.get("paciente","")
    firmas_prev = data.get("firmasPrev","")
    firma_gan   = data.get("firmaGanadora","")
    cantidad    = data.get("cantidad","1")
    n_unit, fmt_unit = fmt_precio(data.get("precioUnit","0"))
    n_tot,  fmt_tot  = fmt_precio(data.get("precioTotal","0"))
    imp_letras  = data.get("importeLetras","")
    pu = "$ " + fmt_unit + ",00"
    pt = " $      " + fmt_tot + ",00 "
    im = "$ " + fmt_tot + ",00 "
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zout:
        for name, b64 in TMPL_AUDIO.items():
            raw = base64.b64decode(b64)
            if name == "[Content_Types].xml":
                xml = raw.decode("utf-8").replace(
                    "application/vnd.ms-word.template.macroEnabledTemplate.main+xml",
                    "application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml")
                raw = xml.encode("utf-8")
            elif name == "word/document.xml":
                xml = raw.decode("utf-8")
                xml = xml.replace("__FECHA__", fecha).replace("__NRO_RES__", nro_res)
                xml = xml.replace("__NRO_EXP__", nro_exp).replace("__PACIENTE__", paciente)
                xml = xml.replace("__FIRMAS_PREV__", firmas_prev)
                xml = xml.replace("__FIRMA_GANADORA_UPPER__", firma_gan.upper())
                xml = xml.replace("__FIRMA_GANADORA__", firma_gan)
                xml = xml.replace("__FIRMA_GANADORA_SHORT__", firma_gan.split("(")[0].strip())
                xml = xml.replace("__CANTIDAD__", cantidad)
                xml = xml.replace("__PRECIO_UNIT__", pu)
                xml = xml.replace("__PRECIO_TOTAL__", pt)
                xml = xml.replace("__IMPORTE__", im)
                xml = xml.replace("__IMPORTE_LETRAS__", imp_letras)
                raw = xml.encode("utf-8")
            zout.writestr(name, raw)
    return buf.getvalue()

class handler(BaseHTTPRequestHandler):
    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length)
        data = json.loads(body)
        tipo = data.get("tipo","anteojos")
        try:
            if tipo == "audio":
                docx = generar_audio(data)
            else:
                docx = generar_anteojos(data)
            apellido = data.get("paciente","").split(",")[0].strip().replace(" ","_")
            nombre = f"Resolucion_{data.get('nroRes','0')}_{apellido}.docx"
            self.send_response(200)
            self.send_header("Content-Type","application/vnd.openxmlformats-officedocument.wordprocessingml.document")
            self.send_header("Content-Disposition", f'attachment; filename="{nombre}"')
            self.send_header("Content-Length", str(len(docx)))
            self.end_headers()
            self.wfile.write(docx)
        except Exception as e:
            self.send_response(500)
            self.send_header("Content-Type","application/json")
            self.end_headers()
            self.wfile.write(json.dumps({"error": str(e)}).encode())
